const AFTER: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/❌delete-rule/🚫️removes-the-wall-wall-rule/📸️snapshot/➡️after/🔣️.json");
const MUTATION: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/❌delete-rule/🚫️removes-the-wall-wall-rule/🦠️mutation/🔣️.json");
const DIFF: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/❌delete-rule/🚫️removes-the-wall-wall-rule/🔺️diff/🔣️.json");
const OUTCOME: &str = include_str!("../../../../../🧫️fixtures/🧬️mutations/❌delete-rule/🚫️removes-the-wall-wall-rule/🎯️outcome/🔣️.json");

fn before() -> Wfc2dSnapshot {
    dsl::json::from_json_str(BEFORE).expect("before snapshot decodes")
}
fn expected_after() -> Wfc2dSnapshot {
    dsl::json::from_json_str(AFTER).expect("after snapshot decodes")
}
fn mutation() -> Wfc2dMutation {
    dsl::json::from_json_str(MUTATION).expect("mutation decodes")
}

/// ▶️ The mutation carries `before` to exactly the committed `after`.
#[test]
fn applies_to_committed_after() {
    let mut snapshot = before();
    apply_wfc2d_mutation(&mut snapshot, &mutation()).expect("mutation applies to its committed before-snapshot");
    assert_eq!(snapshot, expected_after(), "delete-rule/🚫️removes-the-wall-wall-rule: applied state differs from the committed after-snapshot");
}

/// ↩️ Applying the mutation then its inverse restores `before` exactly — VALUE and POSITION.
#[test]
fn inverse_restores_before() {
    let base = before();
    let mutation = mutation();
    let inverse = inverse_wfc2d_mutation(&base, &mutation).expect("valid retained mutation inverse fixture");
    let mut snapshot = base.clone();
    apply_wfc2d_mutation(&mut snapshot, &mutation).expect("forward applies");
    for step in &inverse {
        apply_wfc2d_mutation(&mut snapshot, step).expect("inverse step applies");
    }
    assert_eq!(snapshot, base, "delete-rule/🚫️removes-the-wall-wall-rule: inverse did not restore the before-snapshot");
}

/// 🔣️ Both committed snapshots and the mutation are already canonical: decode→encode is a fixed point.
#[test]
fn committed_json_is_canonical() {
    for (side, text) in [("before", BEFORE), ("after", AFTER)] {
        let decoded: Wfc2dSnapshot = dsl::json::from_json_str(text).expect("snapshot decodes");
        let reencoded = serde_json::from_str::<serde_json::Value>(&dsl::json::to_json_string(&decoded)).expect("snapshot encodes");
        let original: serde_json::Value = serde_json::from_str(text).expect("snapshot reparses");
        assert_eq!(reencoded, original, "delete-rule/🚫️removes-the-wall-wall-rule: committed {side} JSON is not canonical");
