            assert_ne!(snapshot, before(), "change-seed/🎲️reseeds: declared applied but the snapshot came back unchanged");
        }
        "rejected" => {
            assert_eq!(snapshot, before(), "change-seed/🎲️reseeds: a rejected mutation must leave the snapshot untouched");
