const GRID2D_RETAINED_RAW_BYTES: usize = 65_536;
/// 📬️ Admission envelope for one published document edit — `change-tile-media` again.
const GRID2D_ARTIFACT_MUTATION_MAXIMUM_BYTES: usize = 262_144;

